import{_ as a,o as t,c as s,ag as n}from"./chunks/framework.WIXs2PCf.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home"},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),i={name:"index.md"};function o(r,e,l,p,d,h){return t(),s("div",null,[...e[0]||(e[0]=[n(`<section class="prompt-hero" aria-labelledby="add-it-to-your-website-in-one-prompt"><div class="prompt-intro"><p class="prompt-eyebrow">FS AI AGENCY <span>/</span> WEBSITE INTEGRATIONS</p><h1 id="add-it-to-your-website-in-one-prompt">Add the FSAi Funnel to a site<br><span>In one prompt.</span></h1><p class="prompt-description">Open your website project. Give your agent the prompt. Make it yours.</p></div><div class="agent-prompt"><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Add a FranchiseAI qualification flow to this existing website.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>First read https://franchiseai.github.io/website-integrations/llms-full.txt and inspect this project&#39;s framework, routes, components and design system. Use @franchiseai/website-integrations and its documented controller/hook API. Check React 19 compatibility before installing; don&#39;t silently upgrade the site&#39;s framework.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Build the flow into the site&#39;s existing enquiry journey, reusing its typography, spacing, components and tone. Keep the UI fully custom and responsive. Use the docs&#39; React/Astro setup and example renderer; preserve configured questions, validation, optional consent, server-controlled outcomes and secure email continuation. Include accessible labels, keyboard focus, progress, back navigation, pending states and recoverable errors.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Start with the demo adapter. Verify qualified, not-qualified, returning-visitor, loading-failure and save/progress-retry scenarios without creating real leads or sending email. Keep one stable controller per enquiry and keep credentials out of URLs, browser storage and logs.</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Make the demo work end to end, run the project&#39;s relevant checks, and show me the result. Then explain the exact live configuration still needed. Connect the live adapter only when I provide the API base URL and published funnel slug or host and authorize a live test. Don&#39;t invent endpoints, qualification rules or an applicant-portal login, and don&#39;t deploy the site automatically.</span></span></code></pre></div></div><div class="prompt-steps"><span><b>01</b> Copy the prompt</span><span><b>02</b> Paste into your coding agent</span><span><b>03</b> Preview it in your site</span></div></section><h2 id="install-once-make-it-your-own" tabindex="-1">Install once. Make it your own. <a class="header-anchor" href="#install-once-make-it-your-own" aria-label="Permalink to &quot;Install once. Make it your own.&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @franchiseai/website-integrations</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react@^19</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> react-dom@^19</span></span></code></pre></div><p>Start with the <a href="./getting-started.html">React/Astro guide</a>, then connect your <a href="./going-live.html">published funnel</a>. The package handles validation, lead capture, configured page saves and server-controlled qualification. You own every pixel.</p><h2 id="built-for-people-and-their-agents" tabindex="-1">Built for people and their agents <a class="header-anchor" href="#built-for-people-and-their-agents" aria-label="Permalink to &quot;Built for people and their agents&quot;">​</a></h2><p>Give your agent <a href="/website-integrations/llms-full.txt">the complete plain-text guide</a>, or install the optional skill:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> franchiseai/website-integrations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> integrate-fsai</span></span></code></pre></div><p>The <a href="/website-integrations/openapi.json">OpenAPI 3.1 document</a> and <a href="/website-integrations/api.html" target="_self">Redoc API reference</a> describe the existing public HTTP endpoints. Website developers should generally use the package rather than reimplementing the workflow.</p><p>Version 0.1 covers qualification and secure email continuation. Enquiries are held in memory; provision and verify the customer’s live configuration before shipping. <a href="./contract.html">Read the scope and boundaries</a>.</p><h2 id="portal-brands-too" tabindex="-1">Portal brands, too. <a class="header-anchor" href="#portal-brands-too" aria-label="Permalink to &quot;Portal brands, too.&quot;">​</a></h2><p>Explore <a href="/website-integrations/playground/?flow=portal">the Portal enrollment prototype</a>: custom initial details, email/password or Google/LinkedIn, then a simulated handoff to the hosted Applicant Portal. Try two designs using the same headless integration.</p><p><a href="./portal.html">Read the Portal guide</a> for the flow, agent prompt and backend requirements. This is a repository-only demo; npm 0.1.0 and the live integration still cover Funnel brands.</p>`,12)])])}const g=a(i,[["render",o]]);export{u as __pageData,g as default};
